# -*- coding: utf-8 -*-
# Each: id, topic, title, given, prove, steps[(statement,reason)], idea, deep (advanced note), trap (common mistake)
PR=[
dict(id='p-vert',t='bas',title='Vertical angles are equal',given='Lines ℓ and m intersect; ∠1 and ∠3 are vertical angles; ∠2 is between them.',prove='∠1 ≅ ∠3',
steps=[('∠1 and ∠2 form a linear pair','Definition of linear pair'),('m∠1 + m∠2 = 180°','Linear pair postulate (supplementary)'),('∠3 and ∠2 form a linear pair','Definition of linear pair'),('m∠3 + m∠2 = 180°','Linear pair postulate'),('m∠1 + m∠2 = m∠3 + m∠2','Substitution (both equal 180°)'),('m∠1 = m∠3','Subtraction property of equality')],
idea='Both angles are supplements of the SAME angle (∠2). Things that are supplementary to the same angle must be equal.',deep='This is the "same-supplement" pattern: if two angles are each supplementary to one angle, they are congruent. Notice the proof never uses the picture, only the postulates, so it works for every pair of crossing lines.',trap='Do not write "vertical angles are equal" as a reason inside this proof — that is what you are proving.'),
dict(id='p-ext',t='par',title='The angles of a triangle add to 180°',given='△ABC.',prove='m∠A + m∠B + m∠C = 180°',
steps=[('Through C draw line ℓ parallel to AB','Parallel postulate: exactly one parallel through a point'),('Name the angles on ℓ: ∠4 beside ∠A-side and ∠5 beside ∠B-side','Construction labels'),('∠4 ≅ ∠A and ∠5 ≅ ∠B','Alternate interior angles of parallel lines are congruent'),('m∠4 + m∠ACB + m∠5 = 180°','Angles along a straight line (ℓ) add to 180°'),('m∠A + m∠ACB + m∠B = 180°','Substitution')],
idea='Add one helper line. A line through C parallel to the base turns the triangle angles into three angles lying along a straight line.',deep='The parallel postulate is essential. In spherical geometry no such parallel exists and triangle angles add to MORE than 180°, which is why this proof is a real piece of Euclidean geometry.',trap='Alternate interior angles are only equal because the lines are parallel — you built the parallel line, so you earned that fact.'),
dict(id='p-iso',t='tri',title='Base angles of an isosceles triangle are equal',given='△ABC with AB = AC; D is the midpoint of BC.',prove='∠B ≅ ∠C',
steps=[('Draw segment AD','Two points determine a line'),('BD = DC','Definition of midpoint'),('AB = AC','Given'),('AD = AD','Reflexive property'),('△ABD ≅ △ACD','SSS'),('∠B ≅ ∠C','CPCTC (corresponding parts of congruent triangles are congruent)')],
idea='To show two angles equal, put them in two triangles you can prove congruent, then use CPCTC.',deep='A different route uses the angle bisector from A and SAS. Both rely on adding an auxiliary segment — the key skill for harder proofs is deciding what to draw.',trap='CPCTC is the LAST step. You may only use it after the triangles are proven congruent.'),
dict(id='p-hl',t='tri',title='A point on the perpendicular bisector is equidistant from the endpoints',given='Line ℓ is the perpendicular bisector of AB at M; P is on ℓ.',prove='PA = PB',
steps=[('AM = MB','Definition of bisector (midpoint)'),('∠PMA and ∠PMB are right angles','Definition of perpendicular'),('∠PMA ≅ ∠PMB','All right angles are congruent'),('PM = PM','Reflexive property'),('△PMA ≅ △PMB','SAS'),('PA = PB','CPCTC')],
idea='The two small triangles on each side of ℓ share side PM. Matching the bisected segment and the right angles gives SAS.',deep='The converse is also true and is how compass constructions work: points equidistant from A and B lie on the perpendicular bisector. Together they say "the perpendicular bisector is exactly the set of equidistant points" — a locus statement.',trap='Make sure the angle sits BETWEEN the two sides you use. Here ∠PMA is between PM and MA — that is why it is SAS.'),
dict(id='p-par',t='quad',title='Opposite sides of a parallelogram are congruent',given='Parallelogram ABCD (AB ∥ DC and AD ∥ BC).',prove='AB = CD and AD = BC',
steps=[('Draw diagonal AC','Two points determine a line'),('∠BAC ≅ ∠DCA','Alternate interior angles (AB ∥ DC)'),('∠BCA ≅ ∠DAC','Alternate interior angles (AD ∥ BC)'),('AC = AC','Reflexive property'),('△ABC ≅ △CDA','ASA'),('AB = CD and BC = DA','CPCTC')],
idea='A diagonal cuts the parallelogram into two triangles. Parallel sides give two pairs of equal angles, and the diagonal is shared.',deep='The same diagonal cut proves opposite ANGLES are equal. Many parallelogram facts come from this single congruence.',trap='Name the congruent triangles with vertices in matching order: △ABC ≅ △CDA, not △ABC ≅ △ACD.'),
dict(id='p-diag',t='quad',title='Diagonals of a parallelogram bisect each other',given='Parallelogram ABCD; diagonals meet at E.',prove='AE = EC and BE = ED',
steps=[('AB ∥ DC','Definition of parallelogram'),('∠BAE ≅ ∠DCE and ∠ABE ≅ ∠CDE','Alternate interior angles'),('AB = CD','Opposite sides of a parallelogram are congruent'),('△ABE ≅ △CDE','ASA'),('AE = EC and BE = ED','CPCTC')],
idea='Two triangles formed by the crossing diagonals are congruent because the parallel sides AB and DC give equal angles.',deep='Reverse it: if diagonals of a quadrilateral bisect each other, it is a parallelogram. That converse is a standard way to PROVE a shape is a parallelogram in coordinate geometry.',trap='The sides you use for ASA must be between the angles: AB is between ∠BAE and ∠ABE.'),
dict(id='p-mid',t='sim',title='Midsegment of a triangle',given='△ABC; D and E are midpoints of AB and AC.',prove='DE ∥ BC and DE = ½BC',
steps=[('AD/AB = AE/AC = ½','Definition of midpoint'),('∠A ≅ ∠A','Reflexive property'),('△ADE ∼ △ABC','SAS similarity'),('∠ADE ≅ ∠ABC','Corresponding angles of similar triangles'),('DE ∥ BC','Equal corresponding angles force parallel lines'),('DE/BC = ½, so DE = ½BC','Corresponding sides of similar triangles are proportional')],
idea='Midpoints give a 1 : 2 ratio on two sides plus a shared angle — exactly SAS similarity with scale factor ½.',deep='This is a special case of the side-splitter theorem. With coordinates you can verify it by the midpoint and slope formulas, which is a good second proof to compare.',trap='SAS ∼ needs the ratios equal and the INCLUDED angle equal; here ∠A is between the two sides.'),
dict(id='p-pyth',t='rt',title='The Pythagorean theorem (similar triangles proof)',given='Right △ABC with right angle at C; altitude CD to hypotenuse AB. Let AB = c, BC = a, CA = b.',prove='a² + b² = c²',
steps=[('△ABC ∼ △CBD ∼ △ACD','AA similarity (each pair shares an acute angle and has a right angle)'),('a/c = BD/a, so a² = c·BD','Corresponding sides of △ABC ∼ △CBD'),('b/c = AD/b, so b² = c·AD','Corresponding sides of △ABC ∼ △ACD'),('a² + b² = c(BD + AD)','Addition property of equality'),('BD + AD = c','Segment addition postulate'),('a² + b² = c²','Substitution')],
idea='The altitude to the hypotenuse makes two small triangles similar to the big one. Each leg is the geometric mean of the hypotenuse and the piece next to it.',deep='This proof shows WHY: it also gives the three "geometric mean" relations used in rt problems: leg² = hypotenuse × adjacent piece, altitude² = product of the two pieces.',trap='Write similarity in matching order (△ABC ∼ △CBD) or your ratios will be crossed.'),
dict(id='p-insc',t='cir',title='Inscribed angle theorem (center on one side)',given='Circle O; inscribed ∠ABC with BC a diameter (O on BC).',prove='m∠ABC = ½ m(arc AC)',
steps=[('Draw radius OA','Two points determine a line'),('OA = OB','All radii of a circle are equal'),('△OAB is isosceles, so ∠OAB ≅ ∠B','Base angles theorem'),('∠AOC is an exterior angle of △OAB','Definition of exterior angle'),('m∠AOC = m∠OAB + m∠B = 2m∠B','Exterior angle theorem; substitution'),('m(arc AC) = m∠AOC','A central angle equals its intercepted arc'),('m∠B = ½ m(arc AC)','Division')],
idea='Hide an isosceles triangle inside the circle using two radii. Its exterior angle is the central angle and doubles the base angle.',deep='The other two cases (center inside, center outside) are handled by drawing the diameter through B and adding or subtracting two copies of this case. That "reduce to a special case" idea shows up all over mathematics.',trap='The inscribed angle must have its VERTEX on the circle. A vertex at the center gives a central angle instead.'),
dict(id='p-tan',t='cir',title='A tangent is perpendicular to the radius (indirect proof)',given='Line t is tangent to circle O at T.',prove='OT ⊥ t',
steps=[('Assume OT is NOT perpendicular to t','Assumption for indirect proof'),('Draw OP ⊥ t with P on t, P ≠ T','Through a point not on a line there is exactly one perpendicular'),('Choose Q on t so that P is the midpoint of TQ','Segment construction'),('OT = OQ','Points T and Q are equidistant from O (△OPT ≅ △OPQ by SAS)'),('Q is on the circle, so t meets the circle twice','Q is on circle O since OQ = OT = radius'),('This contradicts that a tangent meets the circle in exactly one point','Definition of tangent'),('So OT ⊥ t','The assumption was false')],
idea='Suppose the radius is slanted. Then you can find a second point of the line on the circle — but a tangent touches only once. Contradiction.',deep='Indirect proof (proof by contradiction): assume the opposite, derive something impossible, conclude the original claim. It is the right tool when the statement is a "not" or "only one" claim.',trap='In an indirect proof the first line is the NEGATION of what you want, not what you want.'),
dict(id='p-root2',t='log',title='√2 is irrational (Honors indirect proof)',given='√2 is a real number.',prove='√2 is not a fraction of whole numbers',
steps=[('Assume √2 = a/b in lowest terms','Assumption for contradiction'),('2b² = a²','Square both sides; multiply by b²'),('a² is even, so a is even','If a² is even then a is even'),('Write a = 2k; then 2b² = 4k², so b² = 2k²','Substitution'),('b² is even, so b is even','Same reasoning'),('a and b are both even, so the fraction was not in lowest terms','Contradiction with step 1'),('So √2 cannot be written as a/b','The assumption was false')],
idea='Assume it is a fraction in lowest terms. Squaring shows both top and bottom are even — impossible in lowest terms.',deep='This is one of the oldest proofs (ancient Greece). It matters in geometry: the diagonal of a unit square is √2, so lengths exist that no ratio of whole numbers can measure — a big shock to early mathematicians.',trap='"Lowest terms" is what makes the contradiction work. Without it, both being even is not a problem.'),
dict(id='p-aas',t='tri',title='Why AAS works (from ASA)',given='△ABC and △DEF with ∠A ≅ ∠D, ∠B ≅ ∠E, BC = EF (side not between the angles).',prove='△ABC ≅ △DEF',
steps=[('m∠A = m∠D and m∠B = m∠E','Given'),('m∠C = 180° − m∠A − m∠B and m∠F = 180° − m∠D − m∠E','Triangle angle sum theorem'),('∠C ≅ ∠F','Substitution'),('BC = EF','Given'),('△ABC ≅ △DEF','ASA (∠B, BC, ∠C match ∠E, EF, ∠F)')],
idea='If two angles match, the third must match too. That turns a side NOT between two angles into a side that IS between two angles.',deep='This is why AAS needs no separate postulate. It also explains why AAA is not enough: three equal angles say nothing about size.',trap='Any matching side works for AAS, because the third angle is forced to match as well.'),
dict(id='p-ineq',t='tri',title='Exterior angle is bigger than either remote angle',given='△ABC with exterior angle ∠ACD at C (D on extension of BC).',prove='m∠ACD > m∠A',
steps=[('m∠ACD + m∠ACB = 180°','Linear pair'),('m∠A + m∠B + m∠ACB = 180°','Triangle angle sum'),('m∠ACD = m∠A + m∠B','Subtraction (both sums equal 180° − ∠ACB)'),('m∠B > 0','An angle of a triangle has positive measure'),('m∠ACD > m∠A','Substitution; a sum of positives exceeds one part')],
idea='The exterior angle equals the sum of the two remote angles, so it is bigger than each one by the measure of the other.',deep='This inequality powers the triangle inequality theorem and the "larger angle opposite larger side" theorem, so it sits at the base of Chapter 4 style arguments.',trap='Remote interior angles are the two NOT touching the exterior angle.'),
]

